using SyntacticWizardry.Core;
using System.Numerics;
var engine=new Engine(new Registry());var spell=Engine.Starter();void Check(bool b,string m){if(!b)throw new Exception(m);}
Check(engine.Validate(spell)==null,"starter valid");Check(engine.Cost(spell,.75f)==4.5f,"wand cost");Check(engine.Decode(Engine.Encode(spell)).Cells.Count==2,"round trip");var world=new Fake();var root=new ShapeResolution(Vector3.Zero,Vector3.UnitZ,Vector3.UnitY,null,new HashSet<Voxel>(),null);Check(engine.Execute(world,spell,root)==1&&world.Amount==1,"hit");world.Miss=true;Check(engine.Execute(world,spell,root)==0,"miss stops continuation");spell.Cells[1].Settings["potence"]=11;Check(engine.Validate(spell)!=null,"reject bad potency");spell.Cells[1].Settings.Clear();spell.Cells[1].Row=2;Check(engine.Validate(spell)!=null,"reject gap");Console.WriteLine("Core tests passed");
class Fake:ISpellWorld {public bool Miss;public int Amount;public bool IsLiving(long id)=>id==1;public bool Damage(long id,int amount){Amount+=amount;return true;}public IEnumerable<long> LivingIn(IReadOnlySet<Voxel> v)=>Array.Empty<long>();public ShapeResolution? Trace(ShapeResolution p,TargetMode m,bool i,double r,Func<long,bool>a)=>Miss||!a(1)?null:p with{DirectEntity=1};}
